use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,io::Read,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/bounded-coalesce176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-bounded-coalesce176";
fn p(s:impl AsRef<Path>)->PathBuf{Path::new(R).join(s)}fn d(s:impl AsRef<Path>)->PathBuf{Path::new(D).join(s)}
fn read(x:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(x).unwrap()).unwrap()}
fn save(x:impl AsRef<Path>,v:&Value){fs::write(x,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(x:impl AsRef<Path>)->String{let mut f=fs::File::open(x).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn pins(file:&str){for(x,h)in read(p(file)).as_object().unwrap(){assert_eq!(hash(x),h.as_str().unwrap());}}
fn setup(){pins("pins.json");pins("pins-fixed.json");assert!(!p("review-plan.json").exists());let mut m=read(p("pins-fixed.json")).as_object().unwrap().clone();for name in["review.rs","publish.rs","publisher","report.md","analysis.json","1x2-A.json","1x2-B.json","2x2-A.json","2x2-B.json","runs-fixed/result.json"]{let q=p(name);m.insert(q.display().to_string(),json!(hash(&q)));}save(p("review-pins.json"),&json!(m));save(p("review-plan.json"),&json!({"version":1,"source_pins":p("review-pins.json"),"steps":[{"kind":"link-sdk","name":"review","artifacts":"/home/ubuntu/src/zopro-perf-work/g2-vector-sign-default175/frozen-candidate-cargo.jsonl","driver":p("review.rs"),"additional_sources":["/home/ubuntu/src/zopro-perf-work/g2-balanced-count175/split.rs"],"timeout_seconds":600},{"kind":"command","name":"review-run","argv":[p("review-runs/review-sdk")],"timeout_seconds":600}]}));println!("Prepared independent sorted-row review; no test/count repetition");}
fn walk(dir:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(dir).unwrap(){let p=e.unwrap().path();if p.is_dir(){walk(&p,out)}else{out.push(p)}}}
fn receipts(root:&str)->Value{let mut paths=vec![];walk(&p(root),&mut paths);paths.sort();let mut m=BTreeMap::new();for f in paths{let name=f.strip_prefix(p(root)).unwrap().display().to_string();if name.ends_with("-sdk"){continue}assert!(f.extension().is_some_and(|e|e=="json"||e=="log"));m.insert(name,fs::read_to_string(&f).unwrap());}json!(m)}
fn commands(root:&str,expected:usize,ok:bool){let mut n=0;for e in fs::read_dir(p(root)).unwrap(){let q=e.unwrap().path();if !q.is_dir(){continue}let exit=read(q.join("exit.json"));assert_eq!(exit["success"],ok);assert_eq!(exit["returncode"],if ok{0}else{1});for s in["stdout","stderr"]{assert_eq!(hash(q.join(format!("{s}.log"))),exit[format!("{s}_sha256")]);}if q.join("artifacts.json").exists(){let a=read(q.join("artifacts.json"));for(f,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(f),h.as_str().unwrap());}assert_eq!(hash(a["binary"].as_str().unwrap()),a["binary_sha256"]);}n+=1;}assert_eq!(n,expected);}
fn publish(){
 for file in["pins.json","pins-fixed.json","review-pins.json"]{pins(file)}assert_eq!(read(p("runs-fixed/result.json"))["status"],"complete");assert_eq!(read(p("review-runs/result.json"))["status"],"complete");commands("runs",1,false);commands("runs-fixed",7,true);commands("review-runs",2,true);
 assert_eq!(read(p("analysis.json"))["necessary_opportunity_passed"],true);assert_eq!(read(p("review.json"))["complete"],true);
 let orig=fs::read_to_string(p("model.rs")).unwrap();let fixed=fs::read_to_string(p("model-fixed.rs")).unwrap();assert_eq!(fixed,orig.replacen("n in[0,1,7,1023","n in[0usize,1,7,1023",1));
 assert!(!d("README.md").exists());fs::create_dir_all(d("artifacts")).unwrap();
 for name in["model.rs","model-fixed.rs","probe.rs","probe-fixed.rs","workflow.rs","repair.rs","publish.rs","review.rs","design.md","analysis.json","1x2-A.json","1x2-B.json","2x2-A.json","2x2-B.json","source-review.json","inputs.json","pins.json","pins-fixed.json","plan.json","plan-fixed.json","review-pins.json","review-plan.json","review.json","setup.log","workflow.log","repair-setup.log","workflow-fixed.log","finish.log","review-workflow.log"]{fs::copy(p(name),d("artifacts").join(name)).unwrap();}
 fs::copy("/home/ubuntu/src/zopro-perf-work/g2-balanced-count175/split.rs",d("artifacts/split.rs")).unwrap();fs::copy("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json",d("artifacts/accepted-manifest.json")).unwrap();
 let r=json!({"initial-failed":receipts("runs"),"corrected":receipts("runs-fixed"),"independent-review":receipts("review-runs")});fs::write(p("receipts.json"),serde_json::to_vec(&r).unwrap()).unwrap();let gz=Command::new("gzip").args(["-n","-c"]).arg(p("receipts.json")).output().unwrap();assert!(gz.status.success());fs::write(d("artifacts/receipts.json.gz"),gz.stdout).unwrap();let unpack=Command::new("gzip").args(["-d","-c"]).arg(d("artifacts/receipts.json.gz")).output().unwrap();assert!(unpack.status.success());assert_eq!(unpack.stdout,fs::read(p("receipts.json")).unwrap());
 fs::copy(p("report.md"),d("README.md")).unwrap();
 save(d("artifacts/publication-review.json"),&json!({"complete":true,"successful_workflow_commands":9,"preserved_initial_failed_compiles":1,"all_command_stream_hashes":true,"all_source_helper_library_input_pins_match":true,"tested_model_differs_only_in_test_type_annotation":true,"receipt_archive_exact":true,"native_candidate_exists":false,"performance_claim":false,"private_input_arrays_published":false,"production_changed":false,"new_proofs":0}));
 let text=fs::read_to_string(d("README.md")).unwrap();let mut links=0;for s in text.split("](").skip(1){let target=s.split(')').next().unwrap();if target.starts_with("http"){continue}let q=Path::new(D).join(target);if target!="SHA256SUMS"{assert!(q.is_file(),"missing link {target}");}links+=1;}
 let mut files=vec![];walk(Path::new(D),&mut files);files.sort();let mut sums=String::new();for f in files{sums.push_str(&format!("{}  {}\n",hash(&f),f.strip_prefix(D).unwrap().display()));}fs::write(d("SHA256SUMS"),sums).unwrap();println!("Published bounded-coalescing opportunity, 9successful/1failed commands retained, receipt roundtrip and {links}local links checked; no proof/speedup");
}
fn main(){match std::env::args().nth(1).as_deref(){Some("setup")=>setup(),Some("publish")=>publish(),_=>panic!("setup/publish")}}
